// Shared beginner help for the browser editor and generated reading views.
export const purpose = 'Branchi keeps a memory and a visual map of a project: what you wanted to achieve, what you decided, what you saved and what to do next.';
export const examples = [
 {name:'Plan something at home',goal:'Organise a room makeover or a move.',keeps:'Your requirements, options, budget notes, decisions and the next job.',prompt:'Help me plan a small room makeover. Keep my budget and must-haves visible. Separate decisions from ideas I am still considering.'},
 {name:'Manage job applications',goal:'Keep several applications and document versions organised.',keeps:'Role requirements, document links, confirmed experience and follow-up tasks.',prompt:'Organise this job application around the role requirements. Record which documents I prepared and what still needs checking.'},
 {name:'Learn a subject',goal:'Learn photography, a language or another skill over several sessions.',keeps:'Topics, questions, practice tasks and links to useful explanations.',prompt:'Help me learn photography in small steps. Record what I have practised and suggest one next exercise.'},
 {name:'Make or build something',goal:'Develop a craft project, prototype or small app.',keeps:'The original goal, alternative designs, dependencies, files and test results.',prompt:'Keep a record of this build. Separate proposed ideas, things I made and things I actually tested.'},
 {name:'Research a decision',goal:'Compare options for a purchase or a project.',keeps:'Your requirements, source links, open questions and reasons for your choice.',prompt:'Compare these options against my requirements. Keep the source links and explain why I chose the final option.'},
 {name:'Create something over time',goal:'Plan a story, guide, video series or small business idea.',keeps:'The outline, alternative directions, drafts, feedback and next steps.',prompt:'Keep the main direction clear. Save interesting offshoots for later and record the next useful step.'}
];
export const firstSteps = [
 'Choose one real project and write what you want to achieve in one or two sentences.',
 'Add a few clear outcomes, such as a finished plan, a checked document or a tested prototype.',
 'Save one useful task, decision or source. Open Edit records in the local browser to add items by hand.',
 'Open the project dashboard or map to see how the saved work connects.',
 'Before stopping, record the next action. On your return, open Home and the project handover.'
];
const escape = s => s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function beginnerMarkdown(){
 return `${purpose}\n\nIt is especially useful when a project takes several conversations, has alternative directions or needs to be picked up after a break.\n\n## What could I use it for?\n\n| Example | What you keep together |\n| --- | --- |\n${examples.map(e=>`| **${e.name}** — ${e.goal} | ${e.keeps} |`).join('\n')}\n\nThese are examples to try, not completed projects or promised outcomes.\n\n## Your first five minutes\n\n${firstSteps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\n## Choose the easiest way to start\n\n- **Already set up on this computer?** Open Home and choose a project. Use Edit records to add things manually; you can start without connecting another AI tool.\n- **Starting from scratch?** Ask someone to install the local companion once. Start with the browser and manual notes; Obsidian and AI connections are optional. The beginner setup instructions are linked below.\n- **Already using a connected AI tool?** Ask it to resume your named project or save a milestone. Automatic capture needs a supported connection and permission for that exact chat.\n- **Prefer a notebook-style app?** Open the same project folder in Obsidian. A vault is simply the folder holding your notes and project record.\n\nInstalling Branchi alone does not import all your chats. Basic manual editing and map generation work without AI. Optional AI mapping needs supported signed-in AI access and uses that account's limits. Saved reports remain reports until their evidence is checked.\n\n## Words you will see\n\n- **Project:** one goal and the work related to it.\n- **Branch:** an alternative direction or idea you can return to later.\n- **Checkpoint:** a saved update about progress, decisions and what comes next.\n- **Evidence:** a supporting source or result, such as a document or a test you actually performed.\n- **Handover / resume brief:** a short summary to help you or a connected AI tool continue.\n\n[Beginner setup, examples and copyable prompts](https://github.com/fuzzwin/branchi/blob/main/docs/getting-started.md)\n\n## Daily routine\n\n`;
}
export function beginnerHTML(){
 return `<p class="form-note">${escape(purpose)}</p><h3>Start with one project</h3><ol>${firstSteps.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><details><summary>Six everyday examples and prompts</summary>${examples.map(e=>`<h3>${escape(e.name)}</h3><p>${escape(e.goal)} ${escape(e.keeps)}</p><blockquote>${escape(e.prompt)}</blockquote>`).join('')}</details><p>Manual use and map generation work without AI. Connected chat capture and AI mapping need separate setup; each chat must be included deliberately.</p><p><a href="https://github.com/fuzzwin/branchi/blob/main/docs/getting-started.md" target="_blank" rel="noopener noreferrer">Plain-language setup guide and examples ↗</a></p>`;
}
